const icon=(id,cls='')=>`<svg class="wl-icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[id]||paths.chip}"/></svg>`;
const graph=()=>`<svg class="wl-chart" viewBox="0 0 500 160" aria-hidden="true"><path class="wl-chart-grid" d="M0 25H500M0 65H500M0 105H500M0 145H500M80 0V160M180 0V160M280 0V160M380 0V160M480 0V160"/><path class="wl-chart-fill" d="M0 130L30 113L60 120L90 68L120 85L150 62L180 78L210 30L240 55L270 44L300 73L330 37L360 50L390 20L420 32L450 12L500 27V160H0Z"/><path class="wl-chart-line" pathLength="1" d="M0 130L30 113L60 120L90 68L120 85L150 62L180 78L210 30L240 55L270 44L300 73L330 37L360 50L390 20L420 32L450 12L500 27"/></svg>`;
const node=(title,sub,ico,cls='',style='')=>`<div class="wl-node ${cls}" style="${style}"><span class="wl-node-icon">${icon(ico)}</span><strong>${title}</strong><small>${sub}</small><i class="wl-socket in"></i><i class="wl-socket out"></i></div>`;
const chip=(name='WinEdge',sub='VISION + DATA')=>`<div class="wl-chip"><div class="wl-chip-pins"></div><div class="wl-chip-face">${icon('chip')}<strong>${name}</strong><span>${sub}</span></div></div>`;
const beam='<span class="wl-beam" aria-hidden="true"><i></i></span>';
const routes=(d,cls='')=>`<svg class="wl-routes ${cls}" viewBox="0 0 1000 600" preserveAspectRatio="none" aria-hidden="true">${d.map((p,i)=>`<path class="wl-route-track" d="${p}"/><path class="wl-route-light" d="${p}" style="--i:${i}"/>`).join('')}</svg>`;

function diagram(id){
 if(id==='connect')return `<div class="wl-connect wl-art"><div class="wl-port-stack">${[['相機 / RTSP','VISION INPUT','camera'],['Modbus','DEVICE SIGNAL','plc'],['OPC UA','INDUSTRIAL DATA','network'],['MC Protocol','PLC CONNECTION','plc'],['SQL','DATABASE','database']].map((a,i)=>`<div class="wl-port" style="--i:${i}">${icon(a[2])}<div><strong>${a[0]}</strong><small>${a[1]}</small></div><b></b></div>`).join('')}</div>${routes([60,180,300,420,540].map(y=>y===300?'M370 300 H610':`M370 ${y} H435 Q485 ${y} 485 ${y<300?y+40:y-40} V${y<300?260:340} Q485 300 540 300 H610`))}<div class="wl-hub">${chip()}<div class="wl-hub-caption"><span></span>現場資訊，在此匯流。</div><div class="wl-hub-ports"><i>INPUT</i><i>AI</i><i>OUTPUT</i></div></div></div>`;
 if(id==='flow')return `<div class="wl-workflow wl-art"><div class="wl-app-chrome"><span><i></i><i></i><i></i></span><b>WinEdge / Workflow</b><em>流程已串接</em></div><div class="wl-flow-canvas">${routes(['M160 165H500H840','M840 165V435H500H160'])}${[['資料輸入','CAMERA / SENSOR','input',16,27.5],['前處理','TRANSFORM','sliders',50,27.5],['AI 推論','MODEL','chip',84,27.5],['條件判斷','CONDITION','branch',84,72.5],['看板呈現','DASHBOARD','dashboard',50,72.5],['資料輸出','SQL / I/O','output',16,72.5]].map((a,i)=>node(a[0],a[1],a[2],'wl-flow-node',`left:${a[3]}%;top:${a[4]}%;--i:${i}`)).join('')}<span class="wl-flow-path-label">資料，沿著你的想法前進。</span></div></div>`;
 if(id==='inference')return `<div class="wl-inference wl-art"><div class="wl-inference-row vision"><div class="wl-lane-title">${icon('camera')}<span>VISION<small>視覺推論</small></span><b>01</b></div><div class="wl-inference-body"><div class="wl-inspection"><img src="./assets/vision/caps.jpg" alt="瓶蓋檢測既有應用畫面"/><div class="wl-scan"></div><i class="wl-detection-box"></i></div>${beam}<div class="wl-model-tags"><b>物件偵測</b><b>分割 · SAM3</b></div></div></div><div class="wl-inference-row data"><div class="wl-lane-title">${icon('chart')}<span>DATA<small>數據推論</small></span><b>02</b></div><div class="wl-inference-body"><div class="wl-data-graph">${graph()}<div class="wl-graph-axis"><span>INPUT</span><span>TIME SERIES</span></div></div>${beam}<div class="wl-model-tags"><b>分類 · 迴歸</b><b>時序模型</b></div></div></div><div class="wl-parallel-result"><i></i><span>雙路並行</span><strong>同一套工作流程</strong><i></i></div></div>`;
 if(id==='rhythm')return `<div class="wl-rhythm wl-art"><div class="wl-queue-panel"><div class="wl-queue-row"><label>保完整<small>KEEP EVERY SAMPLE</small></label><div class="wl-queue-cells">${[1,2,3,4,5].map(n=>`<i style="--i:${n}">0${n}</i>`).join('')}</div></div><div class="wl-queue-row latest"><label>保最新<small>KEEP THE LATEST</small></label><div class="wl-queue-cells">${[1,2,3,4,5].map(n=>`<i style="--i:${n}">0${n}</i>`).join('')}</div></div></div><div class="wl-time-align"><div class="wl-align-heading">${icon('clock')}<b>多來源時序對齊</b><span>SYNC</span></div><div class="wl-timeline"><span>來源 A</span><div>${[0,1,2,3,4,5].map(i=>`<i style="--i:${i}"></i>`).join('')}</div><span>來源 B</span><div>${[0,1,2,3,4,5].map(i=>`<i style="--i:${i}"></i>`).join('')}</div><b class="wl-time-cursor"></b></div></div><div class="wl-schedules">${['全速','固定間隔','每日排程','每週排程'].map((s,i)=>`<span style="--i:${i}"><i></i>${s}</span>`).join('')}</div></div>`;
 if(id==='iterate')return `<div class="wl-iterate wl-art"><div class="wl-preview-console"><div class="wl-app-chrome"><b>LIVE PREVIEW</b><em>即時驗證</em></div><div class="wl-preview-body"><div class="wl-parameters"><small>PARAMETERS</small><strong>調整參數</strong>${[0,1,2].map(i=>`<div class="wl-slider" style="--i:${i}"><i></i></div>`).join('')}<span>預覽 → 建置執行</span></div><div class="wl-preview-chart">${graph()}<span>即時預覽結果</span></div></div></div><div class="wl-runtime">${node('資料輸入','RUNNING','input','wl-running')}${beam}<div class="wl-update-node">${icon('refresh')}<strong>模型節點</strong><div class="wl-update-states"><span>執行中</span><span>暫停 · 熱更新</span><span>恢復執行 ✓</span></div><i class="wl-update-progress"></i></div>${beam}${node('資料輸出','RUNNING','output','wl-running')}</div><p class="wl-art-caption">單一節點，獨立暫停與恢復。</p></div>`;
 if(id==='dashboard')return `<div class="wl-dashboard wl-art"><div class="wl-app-chrome"><b>WinEdge / Dashboard Designer</b><em class="wl-publish">發布完成 ✓</em></div><div class="wl-dashboard-body"><aside class="wl-tools">${[['layers','圖層'],['chart','圖表'],['dashboard','元件'],['sliders','樣式']].map(a=>`<div>${icon(a[0])}<span>${a[1]}</span></div>`).join('')}</aside><div class="wl-board"><div class="wl-board-heading"><strong>產線總覽</strong><span>示意資料</span></div><div class="wl-widget wl-widget-trend"><small>製程趨勢</small>${graph()}<div class="wl-graph-axis"><span>08:00</span><span>12:00</span><span>16:00</span></div></div><div class="wl-widget wl-widget-value"><small>現場溫度</small><strong>24.8<span>°C</span></strong><div class="wl-meter"><i></i></div></div><div class="wl-widget wl-widget-status"><small>設備狀態</small><strong><i></i>運作中</strong><div class="wl-mini-bars">${Array.from({length:12},(_,i)=>`<i style="--i:${i};--h:${25+(i*31)%70}%"></i>`).join('')}</div></div><div class="wl-board-bottom"><span>對齊 / 分組 / 縮放</span><b>CSS ＋ 自訂素材</b></div><i class="wl-design-guide"></i></div></div></div>`;
 if(id==='plugins')return `<div class="wl-plugin-scene wl-art">${routes(['M180 120H350Q500 120 500 300','M820 120H650Q500 120 500 300','M180 480H350Q500 480 500 300','M820 480H650Q500 480 500 300'])}<div class="wl-plugin-center">${chip('WinEdge','PLUGIN ARCHITECTURE')}</div>${[['客製模型','CUSTOM MODEL','chip',0],['產線邏輯','PROCESS LOGIC','branch',1],['看板元件','WIDGET','dashboard',2],['第三方整合','INTEGRATION','plugin',3]].map(a=>node(a[0],a[1],a[2],`wl-module wl-module-${a[3]}`,`--i:${a[3]}`)).join('')}<div class="wl-plugin-orbit"></div></div>`;
 return `<div class="wl-agent wl-art"><div class="wl-agent-sources">${[['RAG','現場知識','book'],['Agent','任務協作','agent'],['Skill','可重用方法','skill']].map((a,i)=>node(a[0],a[1],a[2],'',`--i:${i}`)).join('')}</div><div class="wl-intelligence"><div class="wl-orb" aria-hidden="true"><svg viewBox="0 0 300 300"><circle cx="150" cy="150" r="110"/><ellipse cx="150" cy="150" rx="60" ry="110"/><ellipse cx="150" cy="150" rx="110" ry="40"/><path d="M40 150H260M150 40V260M72 72L228 228M72 228L228 72"/>${[[150,40],[260,150],[150,260],[40,150],[72,72],[228,228],[72,228],[228,72]].map(a=>`<circle class="wl-orb-dot" cx="${a[0]}" cy="${a[1]}" r="4"/>`).join('')}</svg><i></i></div><div class="wl-agent-title"><small>POWERED BY WINCHAT</small><strong>本地 AI Agent</strong><span>知識 × 任務 × 方法</span></div></div><div class="wl-agent-targets"><div>${icon('dashboard')}<span>儀表板巡檢</span><b>01</b></div><div>${icon('chart')}<span>資料統計巡檢</span><b>02</b></div></div><p class="wl-art-caption">讓 WinEdge 的現場資訊，成為可理解的脈絡。</p></div>`;
}
const featureIcons={connect:'network',flow:'branch',inference:'chip',rhythm:'clock',iterate:'refresh',dashboard:'dashboard',plugins:'plugin',agent:'agent'};
const miniArt=id=>`<div class="wl-tile-art" aria-hidden="true">${id==='rhythm'?`<div class="wl-mini-bars">${Array.from({length:14},(_,i)=>`<i style="--i:${i};--h:${20+(i*23)%80}%"></i>`).join('')}</div>`:id==='iterate'?graph():id==='connect'?`<div class="wl-mini-network">${icon('camera')}<i></i>${icon('plc')}<i></i>${icon('database')}</div>`:id==='plugins'?`<div class="wl-mini-modules">${icon('chip')}${icon('dashboard')}${icon('plugin')}</div>`:icon(featureIcons[id])}</div>`;
function summaryHTML(){return `<section class="wl-summary wl-slide"><header><p class="wl-eyebrow">${launchPositioning.eyebrow}</p><h1>貼近每個現場，組合各種 AI。</h1></header><div class="wl-bento">${launchFeatures.map((f,i)=>`<article class="wl-tile wl-tile-${f.id}" style="--i:${i}">${miniArt(f.id)}<div class="wl-tile-copy"><span>${f.en}</span><h2>${f.label}</h2><p>${f.summary}</p></div></article>`).join('')}<div class="wl-bento-core"><span>THE ALL-NEW</span><h2>WinEdge</h2><div class="wl-core-halo" aria-hidden="true"></div><p>${launchPositioning.headline}</p><small>${launchPositioning.domains.map(d=>d.label).join(' · ')}</small></div></div></section>`}
function featureHTML(f,index){return `<section class="wl-feature wl-slide" data-feature="${f.id}"><div class="wl-feature-copy"><p class="wl-eyebrow"><span>${String(index).padStart(2,'0')}</span> ${f.en}</p><h1>${f.title.replace('，','，<br>').replace('。持續','。<br>持續')}</h1><p class="wl-description">${f.description}</p><ul>${f.points.map(p=>`<li>${p}</li>`).join('')}</ul></div><div class="wl-feature-stage">${diagram(f.id)}<span class="wl-diagram-note">功能概念動畫</span></div></section>`}
function heroHTML(){return `<section class="wl-hero wl-slide"><div class="wl-hero-copy"><p class="wl-eyebrow">${launchPositioning.eyebrow}</p><h1>WinEdge<span>${launchPositioning.headline.replace(' AI ','<br>AI ')}</span></h1><p>將影像、數據與各種 AI 能力，<br>組合成現場真正需要的應用。</p><div class="wl-hero-origin"><span>WinEdge-N</span><i>＋</i><span>WinEdge-V</span><b>→</b><strong>WinEdge</strong></div></div><div class="wl-hero-orbit" aria-hidden="true"></div><div class="wl-field-applications"><p>依現場需求，自由組合。</p><ul aria-label="WinEdge 現場 AI 應用">${launchPositioning.domains.map((d,i)=>`<li style="--i:${i}">${icon(d.icon)}<span>${d.label}</span></li>`).join('')}</ul></div><span class="wl-hero-caption">ONE PLATFORM. EVERY FIELD.</span></section>`}
function casesHTML(){return `<section class="wl-cases wl-slide"><header><div><p class="wl-eyebrow">BUILT FROM REAL EXPERIENCE</p><h1>從真實現場，走向整合。</h1></div><p>影像、數據與知識。<br>每一份實戰，都是新平台的起點。</p></header><div class="wl-case-grid"><article class="wl-case-main"><div class="wl-case-film"><video muted loop playsinline preload="metadata" poster="./assets/vision/caps.jpg" aria-label="瓶蓋瑕疵檢測應用展示影片"><source src="./assets/vision/caps.mp4" type="video/mp4"></video><button class="wl-video-play" hidden aria-label="播放瓶蓋檢測影片">播放案例影片 ▷</button><span class="wl-case-badge">VISION / 應用展示</span></div><div class="wl-case-copy"><span>01 / 食品飲料</span><h2>瓶蓋瑕疵檢測</h2><p>從產線影像辨識瓶蓋品質，<br>將瑕疵判讀整理成可追蹤的檢測結果。</p></div></article><article class="wl-case-side oven"><div class="wl-case-image"><img src="./assets/pitch-oven-temperature.png" alt="Pitch 中智慧烤箱溫控的多點溫度曲線"/></div><div class="wl-case-copy"><span>02 / DATA</span><h2>智慧烤箱溫控</h2><p>27 個風門 × 15 個溫度點<br>NumOps ＋ WinEdge-N</p></div></article><article class="wl-case-side knowledge"><div class="wl-case-image"><img src="./assets/pitch-winchat.png" alt="WinChat 企業知識問答的產品畫面"/></div><div class="wl-case-copy"><span>03 / KNOWLEDGE</span><h2>企業知識問答</h2><p>文件知識 × 來源引用<br>WinChat RAG</p></div></article></div><p class="wl-case-provenance">既有產品與專案展示｜AIWin Pitch v5 · p.46 / p.34 / p.20、38</p></section>`}

export function createWinEdgeLaunch({container,onChange=()=>{}}){
 let current=0,active=false,busy=false,generation=0,animations=[];
 const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
 const mode=()=>current===0?'hero':current===launchCaseStep?'cases':current===launchLastStep?'summary':'feature';
 function notify(){onChange({step:current,last:launchLastStep,mode:mode(),busy,feature:launchFeatures[current-1]})}
 function cancel(){generation++;animations.forEach(a=>a.cancel());animations=[];busy=false}
 function stopMedia(){container.querySelectorAll('.wl-root video').forEach(v=>{v.pause();v.removeAttribute('src');v.querySelectorAll('source').forEach(s=>s.removeAttribute('src'));v.load()})}
 function playMedia(){const v=container.querySelector('.wl-root video'),button=container.querySelector('.wl-video-play');if(!v)return;v.play().then(()=>{if(button?.isConnected)button.hidden=true}).catch(()=>{if(button?.isConnected)button.hidden=false})}
 function render(){
  container.innerHTML=`<div class="wl-root" data-mode="${mode()}"><div class="wl-content" aria-live="polite" aria-atomic="true">${current===0?heroHTML():current===launchCaseStep?casesHTML():current===launchLastStep?summaryHTML():featureHTML(launchFeatures[current-1],current)}</div><div class="wl-transit" aria-hidden="true"></div></div>`;
  if(current===launchCaseStep&&!reduced)playMedia();
  else if(current===launchCaseStep)container.querySelector('.wl-video-play').hidden=false;
 }
 async function show(next){
  if(!active||busy||next<0||next>launchLastStep||!Number.isInteger(next))return false;
  cancel();const ticket=generation;busy=true;notify();
  const outgoing=container.querySelector('.wl-content');
  if(!reduced&&outgoing){const a=outgoing.animate([{opacity:1,transform:'translateY(0) scale(1)'},{opacity:0,transform:'translateY(-16px) scale(.97)'}],{duration:260,easing:'ease-in',fill:'forwards'});animations.push(a);await a.finished.catch(()=>{});if(ticket!==generation||!active)return false}
  stopMedia();current=next;render();notify();
  if(!reduced){const content=container.querySelector('.wl-content'),sweep=container.querySelector('.wl-transit');const a=content.animate([{opacity:0,transform:'translateY(28px) scale(.96)'},{opacity:1,transform:'translateY(0) scale(1)'}],{duration:1000,easing:'cubic-bezier(.16,1,.3,1)'});const b=sweep.animate([{opacity:0,transform:'translateX(-110%) skewX(-18deg)'},{opacity:.7,offset:.35},{opacity:0,transform:'translateX(110%) skewX(-18deg)'}],{duration:1100,easing:'ease-in-out'});animations.push(a,b);await Promise.all([a.finished.catch(()=>{}),b.finished.catch(()=>{})]);if(ticket!==generation||!active)return false}
  animations=[];busy=false;notify();return true;
 }
 container.addEventListener('click',e=>{if(active&&e.target.closest('.wl-video-play'))playMedia()});
 return {start(){cancel();stopMedia();active=true;current=0;render();notify()},stop(){active=false;cancel();stopMedia();container.querySelectorAll('.wl-root').forEach(e=>e.remove())},next(){if(!active)return false;if(busy)return true;if(current===launchLastStep)return false;show(current+1);return true},previous(){if(!active||current===0&&!busy)return false;if(!busy)show(current-1);return true},state:()=>({current,active,busy})};
}
